    __shared__ scalar_t As[TILE_SIZE][TILE_SIZE];
    __shared__ scalar_t Bs[TILE_SIZE][TILE_SIZE];

    // Calculate row and column of C element
    int row = by * TILE_SIZE + ty;
    int col = bx * TILE_SIZE + tx;

    scalar_t sum = 0;

    // Loop over tiles with unrolling
    int num_tiles = (N + TILE_SIZE - 1) / TILE_SIZE;
    for (int t = 0; t < num_tiles; t += UNROLL_FACTOR) {

        // Preload multiple tiles into shared memory
        #pragma unroll
        for (int u = 0; u < UNROLL_FACTOR; u++) {
            int tile_idx = t + u;
            if (tile_idx < num_tiles) {
                // Load tile from A
                if (row < N && (tile_idx * TILE_SIZE + tx) < N) {
                    As[ty][tx] = A[row * N + (tile_idx * TILE_SIZE + tx)];
                } else {
                    As[ty][tx] = 0;
                }

                // Load tile from B
                if (col < N && (tile_idx * TILE_SIZE + ty) < N) {
                    Bs[ty][tx] = B[(tile_idx * TILE_SIZE + ty) * N + col];
                } else {
                    Bs[ty][tx] = 0;
                }
            }
        }

        __syncthreads();

        // Compute partial dot products for unrolled tiles
        #pragma unroll
        for (int u = 0; u < UNROLL_FACTOR; u++) {
            int tile_idx = t + u;
            if (tile_idx < num_tiles) {
                for (int k = 0; k < TILE_SIZE; k++) {
                    sum += As[ty][k] * Bs[k][tx];
                }
            }
        }

        __syncthreads();
    }

    // Write result to C
    if (row < N && col < N) {
        C[row * N + col] = sum;
    }
