import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define CUDA kernel for matrix multiplication with register blocking
matmul_kernel_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

template <typename scalar_t>
__global__ void matmul_kernel(
    const scalar_t* A,
    const scalar_t* B,
    scalar_t* C,
    int N) {

    // Block index
    int bx = blockIdx.x;
    int by = blockIdx.y;

    // Thread index
    int tx = threadIdx.x;
    int ty = threadIdx.y;

    // Tile dimensions
    const int TILE_SIZE = 16;
    const int BLOCK_SIZE = 4;  // Register tile size (4x4)

    // Allocate shared memory for tiles
    __shared__ scalar_t As[TILE_SIZE][TILE_SIZE];
    __shared__ scalar_t Bs[TILE_SIZE][TILE_SIZE];

    // Calculate row and column of C element
    int row = by * TILE_SIZE + ty;
    int col = bx * TILE_SIZE + tx;

    // Register accumulation
    scalar_t C_reg[BLOCK_SIZE][BLOCK_SIZE] = {{0}};

    // Loop over tiles
    for (int t = 0; t < (N + TILE_SIZE - 1) / TILE_SIZE; ++t) {

        // Load tile from A into shared memory
        if (row < N && (t * TILE_SIZE + tx) < N) {
            As[ty][tx] = A[row * N + (t * TILE_SIZE + tx)];
        } else {
            As[ty][tx] = 0;
        }

        // Load tile from B into shared memory
        if (col < N && (t * TILE_SIZE + ty) < N) {
            Bs[ty][tx] = B[(t * TILE_SIZE + ty) * N + col];
        } else {
            Bs[ty][tx] = 0;
        }

        __syncthreads();

        // Compute partial dot product using register blocking
        for (int k = 0; k < TILE_SIZE; k += BLOCK_SIZE) {
            for (int i = 0; i < BLOCK_SIZE; i++) {
                for (int j = 0; j < BLOCK_SIZE; j++) {
                    C_reg[i][j] += As[ty][k + i] * Bs[k + i][tx + j];
                }
            }
        }

        __syncthreads();
    }

    // Write result to C
    if (row < N && col < N) {
        for (int i = 0; i < BLOCK_SIZE; i++) {
            for (int j = 0; j < BLOCK_SIZE; j++) {
                if ((row + i) < N && (col + j) < N) {
                    C[(row + i) * N + (col + j)] = C_reg[i][j];
                }
            }
        }
    }
}

